export function keyScope(connection){return connection.provider==='custom'?customEndpoint(connection.baseUrl,connection.format):PROVIDERS[connection.provider].origin+PROVIDERS[connection.provider].path;}
export const canStoreKey=()=>['saveApiKey','readApiKey','deleteApiKey'].every(k=>typeof globalThis.CareNotesNative?.[k]==='function');
export function storedKey(connection){try{return canStoreKey()?globalThis.CareNotesNative.readApiKey(keyScope(connection)):'';}catch{return '';}}
export function saveKey(connection){try{return canStoreKey()&&globalThis.CareNotesNative.saveApiKey(keyScope(connection),connection.apiKey)===true;}catch{return false;}}
export function forgetKey(connection){try{return canStoreKey()&&globalThis.CareNotesNative.deleteApiKey(keyScope(connection))===true;}catch{return false;}}

